#include <algorithm>
#include <iostream>
#include <iterator>
#include <vector>

int main() {
    std::vector<int> v;

    std::generate_n(std::back_insert_iterator<std::vector<int>>(v),
        // Or use std::back_inserter helper
        // Or use std::back_insert_iterator(v) C++17's syntax
        10, [n = 0]() mutable { return ++n; });

    for (int n : v)
        std::cout << n << ' ';
    std::cout << '\n';
}
